using System.Net;
using System.Net.Http.Json;
using UnscRelay.Core;
internal static class SharingControlChecks
{
 sealed class Server(ArchiveSharingReview review):HttpMessageHandler{public int Requests;public bool Fail;protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken ct){Requests++;if(request.RequestUri!.Scheme!="https"||request.RequestUri.Host!="unsc.responda.eu"||request.Headers.Authorization?.Parameter!="synthetic-access")throw new Exception("Unexpected sharing transport");return Task.FromResult(new HttpResponseMessage(Fail?HttpStatusCode.ServiceUnavailable:HttpStatusCode.OK){Content=JsonContent.Create(Fail?(object)new{error="Synthetic outage"}:review,options:VaultSyncCrypto.Json)});}}
 public static async Task<int> Run(){var root=Directory.CreateTempSubdirectory("relay-sharing-controls-");var count=0;void Check(bool v,string label){if(!v)throw new Exception(label);count++;Console.WriteLine("PASS sharing controls: "+label);}try{var id=Guid.NewGuid();var member=new ArchiveSharingReviewMember(new string('A',64),"fixture@example.invalid","read","2030-01-01T12:00:00+00:00");string[] fields=["archive.sharing.pause",id.ToString("D"),"4","false","true",member.Account,member.Access,member.ExpiresAt!];var review=new ArchiveSharingReview(id,false,true,4,fields[0],fields[1],CloudAccountClient.SensitiveIntentHash(fields),fields,[member]);CloudAccountClient.ValidateSharingReview(review,id,true);Check(true,"exact owner review binds action, resource, version, permission and expiry");foreach(var changed in new[]{review with{ArchiveId=Guid.NewGuid()},review with{RequestedSuspended=false},review with{Version=5},review with{Action="archive.sharing.resume"},review with{Members=[member with{Access="write"}]},review with{Members=[member with{ExpiresAt=null}]},review with{Intent=new string('0',64)}}){try{CloudAccountClient.ValidateSharingReview(changed,id,true);throw new Exception("Changed consent accepted");}catch(InvalidDataException){Check(true,"modified sharing consent is refused");}}
 var server=new Server(review);using var client=new CloudAccountClient(root.FullName,server);try{await client.ReviewArchiveSharing(id,true,CancellationToken.None);throw new Exception("Disconnected review accepted");}catch(OnlineAccessException){Check(server.Requests==0,"disconnected account cannot retrieve private sharing inventory");}client.State.Activated=true;client.State.AccessToken="synthetic-access";client.State.TokenExpires=DateTimeOffset.UtcNow.AddMinutes(5);var received=await client.ReviewArchiveSharing(id,true,CancellationToken.None);Check(received.Intent==review.Intent,"authenticated transport preserves the validated review");server.Fail=true;try{await client.ReviewArchiveSharing(id,true,CancellationToken.None);throw new Exception("Outage accepted");}catch(OnlineAccessException){Check(true,"service failure never produces an editable fabricated review");}foreach(var cell in new[]{"=HYPERLINK(1)","  +SUM(1)","\t@SUM(1)","-2"})Check(ArchivePermissionReport.Cell(cell).StartsWith("\"'",StringComparison.Ordinal),"spreadsheet formula is inert in exported permissions");var report=ArchivePermissionReport.Create(new(id,"A,\"B",new string('A',64),new string('B',64),"owner",1),[new(member.Account,"reader@example.invalid","read",DateTimeOffset.Parse(member.ExpiresAt!))]);Check(report.Contains("\"A,\"\"B\"")&&report.Contains("2030-01-01T12:00:00.0000000+00:00"),"report preserves quoted names and unambiguous UTC expiry");var htmlArchive=new SharedArchive(id,"Équipe München <script>forbidden()</script>",new string('A',64),new string('B',64),"owner",1);var html=ArchivePermissionReport.Html(htmlArchive,[new(member.Account,"<img src=https://example.invalid>","read")],"it",value=>value);Check(!html.Contains("<script>")&&!html.Contains("<img")&&html.Contains("&lt;script&gt;")&&html.Contains("scope=\"col\"")&&html.Contains("lang=\"it\""),"permission document escapes untrusted names and provides semantic localized table headings");foreach(var denied in new[]{htmlArchive with{Access="read"},htmlArchive with{Offline=true}}){try{ArchivePermissionReport.Html(denied,[],"it",value=>value);throw new Exception("Unauthorized permission report");}catch(InvalidOperationException){Check(true,"offline or non-owner report is refused");}}try{ArchivePermissionReport.Html(htmlArchive,Enumerable.Repeat(new SharedArchiveMember(member.Account,"fixture@example.invalid","read"),1001),"it",value=>value);throw new Exception("Unbounded report");}catch(InvalidDataException){Check(true,"oversized permission inventory is refused");}Console.WriteLine("Sharing control checks: "+count);return 0;}finally{root.Delete(true);}}
}
